//! Runtime for inflection crates generated by `flexion-train`.
//!
//! A generated crate (`english`, `russian`, …) is a thin typed API over one
//! [`Model`]: a static blob holding, per part of speech, the **edits** that
//! turn a lemma into its forms, the **inflection classes** (one edit per cell,
//! plus inherent features such as gender), and a **suffix tree** over lemmas
//! read from their last letter backwards. Each tree node stores a probability
//! distribution over classes; walking a word to its deepest matching node
//! gives the classes that word most likely belongs to. Attested exceptions are
//! simply deep nodes, so memorized words and general patterns are one
//! structure.
//!
//! Every function here is total and never panics. A corrupt blob yields no
//! model ([`Model::from_bytes`] returns `None`), and generated crates fall
//! back to returning the input unchanged.

#![deny(clippy::arithmetic_side_effects)]

pub mod format;
mod pos;
pub mod text;
pub mod write;

use format::{Bytes, DIST_LEN, EDIT_LEN, HEADER_LEN, NODE_LEN, NONE, POS_HEADER_LEN, class_len};
pub use pos::{Citation, Edit, Pos};
pub use text::{Casing, Spelling, VowelSet, Word};

/// One possible form, with the model's confidence in it.
#[derive(Debug, Clone, PartialEq)]
pub struct Candidate {
    pub form: String,
    /// Probability in `0.0..=1.0`. Candidates of one call sum to 1.
    pub confidence: f32,
}

/// Output options shared by every query.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Options {
    /// Write stress marks on output (only where the language's data marks
    /// stress).
    pub stress: bool,
}

impl Default for Options {
    fn default() -> Self {
        Options { stress: true }
    }
}

/// A loaded model: a validated view over a static blob.
#[derive(Debug, Clone)]
pub struct Model<'a> {
    pub(crate) bytes: Bytes<'a>,
    pub(crate) strings: &'a str,
    pub(crate) spelling: Spelling<'a>,
    parts: Vec<PosHeader>,
}

#[derive(Debug, Clone, Copy)]
pub(crate) struct PosHeader {
    pub(crate) cells: usize,
    pub(crate) inherent: usize,
    pub(crate) edits: usize,
    pub(crate) n_edits: usize,
    pub(crate) classes: usize,
    pub(crate) n_classes: usize,
    pub(crate) class_len: usize,
    pub(crate) nodes: usize,
    pub(crate) n_nodes: usize,
    pub(crate) dist: usize,
    pub(crate) n_dist: usize,
    pub(crate) lemma_cell: Option<usize>,
    pub(crate) walk: Walk,
}

/// How a key is turned into the sequence of symbols the tree is walked with.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct Walk {
    /// Insert a syllable-count token after this many letters (from the end).
    pub syllable_depth: Option<usize>,
    /// Syllable counts above this share the last bucket.
    pub syllable_max: usize,
}

impl Walk {
    pub fn encode(self) -> u32 {
        match self.syllable_depth {
            Some(d) => {
                (u32::try_from(d).unwrap_or(254).min(254).saturating_add(1))
                    | (u32::try_from(self.syllable_max).unwrap_or(255).min(255) << 8)
            }
            None => 0,
        }
    }

    pub fn decode(v: u32) -> Walk {
        let depth = v & 0xff;
        Walk {
            syllable_depth: (depth != 0)
                .then(|| usize::try_from(depth.saturating_sub(1)).unwrap_or(0)),
            syllable_max: usize::try_from((v >> 8) & 0xff).unwrap_or(0),
        }
    }

    /// The walk for `key`: its letters from the last one back, the syllable
    /// token where configured, then the start-of-word symbol.
    pub fn symbols(self, sp: &Spelling<'_>, key: &str) -> Vec<char> {
        let mut out: Vec<char> = key.chars().rev().collect();
        if let Some(d) = self.syllable_depth {
            let bucket = sp.vowel_groups(key).min(self.syllable_max);
            let token = u32::try_from(bucket)
                .ok()
                .and_then(|b| char::from_u32(format::SYLLABLE_TOKEN.saturating_add(b)));
            if let Some(t) = token {
                out.insert(d.min(out.len()), t);
            }
        }
        out.push(format::BOUNDARY);
        out
    }
}

impl<'a> Model<'a> {
    /// Validate and load a blob written by `flexion-train`.
    pub fn from_bytes(bytes: &'a [u8]) -> Option<Model<'a>> {
        let b = Bytes(bytes);
        if bytes.get(0..4)? != format::MAGIC || b.u32(4)? != format::VERSION {
            return None;
        }
        let s_off = b.usize(8)?;
        let s_len = b.usize(12)?;
        let strings = std::str::from_utf8(bytes.get(s_off..s_off.checked_add(s_len)?)?).ok()?;
        let n_pos = b.usize(16)?;
        let flags = b.u32(20)?;
        let mark = b.str(strings, 24)?;
        let spelling = Spelling {
            fold_case: flags & format::FLAG_FOLD_CASE != 0,
            mark_monosyllables: flags & format::FLAG_MARK_MONOSYLLABLES != 0,
            stress_mark: mark.chars().next(),
            vowels: b.str(strings, 32)?,
            vowel_set: text::VowelSet::new(b.str(strings, 32)?),
            implicit: b.str(strings, 40)?,
            fold_from: b.str(strings, 48)?,
            fold_to: b.str(strings, 56)?,
            strip_marks: b.str(strings, 64)?,
        };
        let mut parts = Vec::with_capacity(n_pos);
        for i in 0..n_pos {
            let at = HEADER_LEN.checked_add(i.checked_mul(POS_HEADER_LEN)?)?;
            let field = |n: usize| b.usize(at.checked_add(n.checked_mul(4)?)?);
            let cells = field(0)?;
            let inherent = field(1)?;
            let lemma = b.u32(at.checked_add(40)?)?;
            let h = PosHeader {
                cells,
                inherent,
                edits: field(2)?,
                n_edits: field(3)?,
                classes: field(4)?,
                n_classes: field(5)?,
                class_len: class_len(cells, inherent),
                nodes: field(6)?,
                n_nodes: field(7)?,
                dist: field(8)?,
                n_dist: field(9)?,
                lemma_cell: (lemma != NONE)
                    .then(|| usize::try_from(lemma).ok())
                    .flatten(),
                walk: Walk::decode(b.u32(at.checked_add(44)?)?),
            };
            // Every table must lie inside the blob.
            let ends = [
                h.edits.checked_add(h.n_edits.checked_mul(EDIT_LEN)?)?,
                h.classes
                    .checked_add(h.n_classes.checked_mul(h.class_len)?)?,
                h.nodes.checked_add(h.n_nodes.checked_mul(NODE_LEN)?)?,
                h.dist.checked_add(h.n_dist.checked_mul(DIST_LEN)?)?,
            ];
            if ends.iter().any(|&e| e > bytes.len()) || h.n_nodes == 0 {
                return None;
            }
            parts.push(h);
        }
        Some(Model {
            bytes: b,
            strings,
            spelling,
            parts,
        })
    }

    pub fn spelling(&self) -> &Spelling<'a> {
        &self.spelling
    }

    /// Part of speech `index`, in the order the language's config declares them.
    pub fn pos(&self, index: usize) -> Option<Pos<'_, 'a>> {
        Some(Pos::new(self, *self.parts.get(index)?))
    }

    pub fn pos_count(&self) -> usize {
        self.parts.len()
    }
}

